<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main">
            <van-form>
                <div class="formCol">
                    <div class="item">
                        <div class="label">{{ appStore.rolelist[userInfo.layer] }}账号</div>
                        <div class="item-rt">
                            {{ userInfo.account }}
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">会员账户</div>
                        <div class="item-rt">
                            <input @change="selects()"  minlength="4" v-model="ruleForm.account" :rules="rules.account" class="addInput" /><span v-if="users" style="color: blue;margin-top: 5px;margin-left:3px;">账户可用</span>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">会员昵称</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.nickName" maxlength="10"  class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">登录密码</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.passwd" :rules="rules.passwd"   class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">状态</div>
                        <div class="item-rt">
                            <van-radio-group class="checkbox" v-model="ruleForm.status" direction="horizontal" placeholder="请选择状态">
                                <van-radio :name="1" icon-size="16px">启用</van-radio>
                                <van-radio :name="2" icon-size="16px">禁用</van-radio>
                                <van-radio :name="3" icon-size="16px">冻结</van-radio>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">{{ userInfo.mode == 1 ? '信用' : '现金' }}额度</div>
                        <div style="display:block">
                            <p style="display:flex;align-items:center">
                               <input  v-model.number="ruleForm.cash"  class="addInput" placeholder="请输入额度" />
                               <span style="margin-left:5px">{{ cash2china }}</span>
                            </p>
                            <p style="font-size:12px;color:#333;padding-top:4px;">(上级余额：{{userTime.isDot(userInfo.cash - userInfo.cashUsed) }})</p>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">抽取退水</div>
                        <div class="item-rt">
                            <select @change="changewater" v-model="value" style="width:56%;margin-right:5px;"
                                    class="select">
                                <option
                                        v-for="(item,index) in waterOtions"
                                        :key="index"
                                        :value="item.value"
                                >
                                    {{ item.label }}
                                </option>
                            </select>
                            <input  v-model.number="ruleForm.ownReback"  class="addInput" placeholder="请输入抽取退水" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">开放盘口</div>
                        <div class="item-rt">
                            <van-radio-group direction="horizontal" v-model="ruleForm.handicap" :rules="rules.handicap">
                                <template v-for="(item,index) in userInfo.handicapList" :key="index + 1">
                                    <van-radio v-if="item == 1" icon-size="16px" :name="item">A盘</van-radio>
                                    <van-radio v-if="item == 2" icon-size="16px" :name="item">B盘</van-radio>
                                    <van-radio v-if="item == 3" icon-size="16px" :name="item">C盘</van-radio>
                                    <van-radio v-if="item == 4" icon-size="16px" :name="item">D盘</van-radio>
                                </template>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">游戏显示</div>
                        <div class="item-rt" style="padding-top:5px;">
                            <van-checkbox-group class="checkbox"  direction="horizontal" v-model="ruleForm.lotlist" @change="selctLottry">
                                <template v-for="(item,index) in yxlist" :key="index + 1">
                                    <van-checkbox style="margin-bottom:5px;width:115px" icon-size="14px" :disabled="item.isNeed == 1" :name="item.lotteryId"  shape="square">{{ item.lotteryName }}</van-checkbox>
                                </template>
                            </van-checkbox-group>
                        </div>
                    </div>
                </div>
                <div class="mixSet">
                    <div class="title blue">占成设置</div>
                    <div class="mixCon">
                        <div style="overflow:auto;padding-bottom:10px">
                            <table style="width:100%">
                                <thead>
                                    <tr>
                                        <th>类型</th>
                                        <th>代理占成</th>
                                        <th>可分配占成</th>
                                    </tr>
                                </thead>
                                <tbody v-if="ruleForm.opcpList.length > 0">
                                    <tr>
                                        <td style="color:#4768B0">快捷设置</td>
                                        <td>
                                            <div class="field">
                                                <van-field type="digit" input-align="center" style="width:90px;" @change="copyOccupy" v-model.number="ruleForm.share" @keyup.native="check_count" class="field input"
                                       size="mini"></van-field>
                                               <span style="width:60px;display:inline-block"></span>
                                            </div>
                                        </td>
                                        <td></td>
                                    </tr>
                                    <tr v-for="(iten,index) in ruleForm.opcpList" :key="iten.lotteryId" v-show="iten.selected" :class="(index % 2 == 0) ? 'eve' : 'old'">
                                        <td>{{ iten.lotteryName }}</td>
                                        <td>
                                            <div class="field">
                                                <van-stepper :show-minus="false" :show-plus="false" :min="iten.minShare" @keyup.native="check_count" integer
                                                            :max="iten.maxShare"
                                                            v-model="iten.share"></van-stepper>
                                                <span style="width:60px;display:inline-block">({{ iten.minShare }}至{{ iten.maxShare }})</span>
                                            </div>
                                        </td>
                                        <td>{{ iten.maxShare }}</td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                        <div class="zzhx">点击确定按钮后，相关信息已经复制，可直接在聊天App粘贴。</div>
                        <div class="fobtn">
                            <div @click="cancelForm" class="fobcanl">取消</div>
                            <div class="fobmits" v-clipboard:copy="copyText" v-clipboard:success="onCopy" v-clipboard:error="onError" @click="membSumbit">确定</div>
                        </div>
                    </div>
                </div>
            </van-form>
        </div>
    </div>
</template>

<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const md5 = useMd5();

// 获取全局实例（用于 md5 和 clipboard）
const { proxy } = getCurrentInstance()


// ==================== 数据定义 ====================
const errorText = ref('')
const users = ref(false)
const yxlist = ref([])
const value = ref(0)
const num = ref(3)
const tits = ref('新增会员')
const props = defineProps(['id'])
const userInfo = ref({
    account: '',
    cash: 0,
    cashUsed: 0,
    searchUrl: '',
    searchCode: '',
    id: '',
    mode: 1,
    handicapList: [],
    lotteryList: [],
    occupyList: [],
    layer: 0,
    role: 0
})

const waterOtions = [
    { value: 0, label: '水全退到底' },
    { value: 0.1, label: '赚取0.1%退水' },
    { value: 0.3, label: '赚取0.3%退水' },
    { value: 0.5, label: '赚取0.5%退水' },
    { value: 1.0, label: '赚取1.0%退水' },
    { value: 1.5, label: '赚取1.5%退水' },
    { value: 2.0, label: '赚取2.0%退水' },
    { value: 2.5, label: '赚取2.5%退水' },
    { value: 99, label: '赚取所有退水' },
]

const ruleForm = reactive({
    orgId: props.id,
    account: '',
    nickName: '',
    passwd: '',
    status: 1,
    cash: '',
    ownDownOdds: 0,
    ownReback: '',
    role: 5,
    handicap: 1,
    handicapList: [],
    lotteryList: [],
    lotlist: [],
    opcpList: [],
    share: '',
    occupyList: [],
    password: '',
    pid: ''
})

// ==================== 验证器函数 ====================
const createMoneyValidator = (userInfoRef, field) => (value) => {
    if (userInfoRef.value[field] == 0 || userInfoRef.value[field] > 0) {
        if (value > userInfoRef.value[field]) {
            return false
        } else {
            return true
        }
    }
    return true
}

// ==================== 表单验证规则 ====================
const rules = reactive({
    account: [
        { required: true, message: '请填写账户', trigger: 'blur' },
        { type: 'string', pattern: /^[\w\d-]{4,}$/, message: '账号使用英文字符、数字4位以上', trigger: 'blur' },
        { min: 4, message: '账户最小4个字符', trigger: 'blur' },
    ],
    passwd: [
        { required: true, message: '请填写登录密码', trigger: 'blur' },
        {
            type: 'string',
            pattern: /(?![^a-zA-Z0-9]+$)(?![^a-zA-Z/D]+$)(?![^0-9/D]+$).{6,20}$/,
            message: '密码由6位以上英文、数字组成',
            trigger: 'blur'
        },
    ],
    cash: [
        { required: true, message: '请填写现金额度', trigger: 'blur' },
        { type: 'number', min: 0, message: '现金额度只能是数字', trigger: 'blur' },
        { validator: createMoneyValidator(userInfo, 'cash'), trigger: 'blur' }
    ],
    handicap: [
        { required: true, message: '请选择开放盘口', trigger: 'change' }
    ],
    ownReback: [
        { required: true, message: '请填写退水', trigger: 'blur' },
        { type: 'number', min: 0, message: '退水只能是数字', trigger: 'change' },
        { type: 'number', min: 0, message: '退水只能是数字', trigger: 'blur' },
    ]
})

// ==================== 计算属性 ====================
const cash2china = computed(() => {
    if (ruleForm.cash * 1 > 0) {
        return nzhcn.encodeS(ruleForm.cash)
    }
    return ''
})

const copyText = computed(() => {
    return `导航:${userInfo.value.searchUrl}\n安全码:${userInfo.value.searchCode}\n账号:${ruleForm.account}\n密码:${ruleForm.passwd}`
})

const check_count = (e) => {
    let obj = e.target
    if (obj.value != '' && obj.value.substr(0, 1) == '.') {
        obj.value = ""
    }
    let result = (obj.value.toString()).indexOf(".")
    if (result != -1) {
        obj.value = ""
    }
    obj.value = obj.value.replace(/\D/g, '')
}

// ==================== 主要方法 ====================
const onCopy = (e) => {
    console.log(e)
}

const onError = (e) => {
    alert("失败")
}

const copyOccupy = () => {
    ruleForm.opcpList.forEach(iten => {
        if (ruleForm.share > iten.minShare) {
            iten.share = ruleForm.share
        } else {
            iten.share = iten.minShare
        }
    })
}

const selects = async () => {
    const reg = /^[a-zA-Z]\w{3,9}$/
    
    if (!ruleForm.account) return
    if (!reg.test(ruleForm.account)) {
        showToast({
            message: '请输入正确账号首个字母为英文加数字组合，4-10位数!',
            icon: 'fail',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        ruleForm.account = ""
        return false
    }
    
    let username = ruleForm.account.toLowerCase()
    try {
        const data = await userStore.checkAcc(username)
        if (data.data) {
            users.value = true
            return true
        } else {
            users.value = false
            ruleForm.account = ''
            showToast({
                message: '账号已存在!',
                icon: 'fail',
                className: 'custom-toast',
                duration: 2000  // 自定义显示时间
            });
            return false
        }
    } catch (error) {
        console.error(error)
    }
}

const changewater = () => {
    ruleForm.ownReback = value.value
}

const selctLottry = () => {
    ruleForm.opcpList.forEach(iten => {
        if (ruleForm.lotlist.includes(parseInt(iten.lotteryId))) {
            iten.selected = true
        } else {
            iten.selected = false
        }
    })
}

const getUserInfo = async () => {
    yxlist.value = []
    ruleForm.opcpList = []
    
    try {
        const res = await userStore.getQueryOrg(props.id)
        userInfo.value = res.data
        ruleForm.handicap = userInfo.value.handicapList[0]
        ruleForm.mode = res.data.mode ? res.data.mode : 1
        
        res.data.occupyList.forEach(iten => {
            iten.share = 0
            iten.selected = true
        })
        
        ruleForm.opcpList = res.data.occupyList
        
        if (userInfo.value.lotteryList.length > 0) {
            yxlist.value = userInfo.value.lotteryList
            yxlist.value.forEach(item => {
                ruleForm.lotlist.push(item.lotteryId)
            })
        }
    } catch (error) {
        console.error(error)
    }
}

const membSumbit = () => {
    if (!ruleForm.passwd) {
        showToast({ type: 'error', message: '密码不能为空值' })
        return false
    }
    addMember()
}

const addMember = async () => {
    if (ruleForm.lotlist.length == 0) {
        showToast({ type: 'error', message: '请至少选择一个显示游戏' })
        return false
    }
    
    const loading = showLoadingToast({
        lock: true,
        duration: 0,
        forbidClick: true,
        mask: true,
        background: 'rgba(0, 0, 0, 0.7)',
        message: '正在加载……'
    })
    
    ruleForm.occupyList = []
    ruleForm.handicapList = []
    ruleForm.lotteryList = []
    ruleForm.handicapList.push(ruleForm.handicap)
    
    yxlist.value.forEach(item => {
        ruleForm.lotlist.forEach(items => {
            if (item.lotteryId == items) {
                ruleForm.lotteryList.push(item)
            }
        })
    })
    
    let tt = []
    let t = ''
    ruleForm.opcpList.forEach(iten => {
        if (iten.selected) {
            tt.push(iten)
        }
        if (iten.share < iten.minShare || iten.share > iten.maxShare) {
            t = 1
            return false
        }
    })
    
    if (t) {
        showToast({
            type: 'error',
            message: '上级占成不能超过最大值或者最低值不能超过最高值'
        })
        loading.close()
        return false
    }
    
    ruleForm.occupyList = tt
    
    let paw = ruleForm.passwd.toLowerCase()
    ruleForm.password = md5(paw)
    ruleForm.pid = userInfo.value.id
    ruleForm.role = 5
    ruleForm.ownReback = ruleForm.ownReback > 0 ? ruleForm.ownReback : 0
    ruleForm.cash = ruleForm.cash > 0 ? ruleForm.cash : 0
    
    setTimeout(() => {
        loading.close()
    }, 5000)
    
    try {
        const res = await userStore.orgAdd(ruleForm)
        loading.close()
        if (res.code == 200) {
            if (res.data != '成功') {
                showConfirmDialog({
                    message: '是否设置退水信息?',
                    title: '提示',
                    confirmButtonText: '是',
                    cancelButtonText: '否',
                }).then(() => {
                    router.push({ path: `/RefundWater/${res.data}` })
                }).catch(() => {
                    router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
                })
            } else {
                router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
            }
        }
    } catch (error) {
        console.error(error)
    }
}

const cancelForm = () => {
    router.push({ name: 'UserManage', params: { pid: userInfo.value.id } })
}

// ==================== 生命周期 ====================
onMounted(() => {
    getUserInfo()
})
</script>

<style scoped>
.page{
    height:100vh;
    background: #EAF2FF;
}
.mixCon :deep(.van-stepper__input){
    width:120px !important;
    height: 35px !important;
    line-height: 35px !important;
    margin-right:5px;
    border: solid 0.3px var(--grey-blue-surface-g-50);
    border-radius: 10px;
    background-image: linear-gradient(180deg, #EAF2FF 0%, #FFF 25%, #FFF 75%, #F2F7FF 100%);
    font-size: 18px;
}
.title {
    margin-top: 30px;
    width: 140px;
    height: 40px;
    background: transparent linear-gradient(180deg, #66BAFF 0%, #3C8EFF 100%, #3C8EFF 100%) 0% 0% no-repeat padding-box;
    box-shadow: 0px 3px 6px #64B7FF;
    border-radius: 0px 17px 17px 0px;
    text-align: center;
    font: normal normal 600 16px/40px Segoe UI;
    letter-spacing: 0px;
    color: #FFFA77;
}
.formCol .item .select {
    width: 160px;
    height: 35px;
    font-size:12px;
    color: #707070;
}
.copyBtn {
    margin-left: 10px;
    width: 69px;
    height: 35px;
    background: transparent linear-gradient(180deg, #66BAFF 0%, #3C8EFF 100%, #3C8EFF 100%) 0% 0% no-repeat padding-box;
    border-radius: 14px;
    text-align: center;
    font: normal normal normal 14px/35px Segoe UI;
    letter-spacing: 0px;
    color: #FFFFFF;
    vertical-align: middle
}

.formCol .item .checkbox {
    overflow: hidden;
}


.mixSet {
    padding: 10px 0 10px;
    margin-top: 5px
}

.mixSet .mixCon .input {
    width: 80px;
}

.mixSet .mixCon {
    max-width: 100%;
    overflow: hidden
}

.mixSet .mixCon .field {
    align-items: center;
    display: flex;
    justify-content: center
}

.mixSet .mixCon .field span {
    margin-left: 5px
}
.item .van-radio--disabled :deep(.van-icon){
    background: #c8c9cc 0% 0% no-repeat padding-box !important; 
    border:1px solid #c8c9cc !important;
    color: #fff;
}
.item .van-checkbox--disabled :deep(.van-icon){
    background: #c8c9cc 0% 0% no-repeat padding-box !important; 
    border:1px solid #c8c9cc !important;
    color: #fff;
}
.item :deep(.van-radio__icon--checked  .van-icon){
    border: 1px solid #5b9dfe !important;
    background: #5b9dfe 0% 0% no-repeat padding-box !important; 
    color: #fff;
}
</style>